import java.util.PriorityQueue;
import java.util.concurrent.atomic.AtomicLong;

record Task(String name, int priority, long seq) {}

PriorityQueue<Task> pq = new PriorityQueue<>(Comparator
    .comparingInt(Task::priority)
    .thenComparingLong(Task::seq));      // seq makes ties FIFO and keeps the comparator total
pq.offer(new Task("write", 5, seq.incrementAndGet()));

Task t = pq.poll();                       // smallest priority first (min-heap by default)

